SET search_path=vcm,pg_catalog;
CREATE TABLE annual_plans(id text PRIMARY KEY,year int NOT NULL CHECK(year BETWEEN 1900 AND 9999),title text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','review','sanctioned','approved')),protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER plan_protect BEFORE INSERT ON annual_plans FOR EACH ROW EXECUTE FUNCTION protect_object('annual_plan');
CREATE TABLE plan_revisions(id text PRIMARY KEY REFERENCES object_revisions(id),plan_id text NOT NULL REFERENCES annual_plans(id),version int NOT NULL CHECK(version>0),reason text NOT NULL,actor_id text NOT NULL REFERENCES principals(id),UNIQUE(plan_id,version));
CREATE TRIGGER plan_revision_register BEFORE INSERT ON plan_revisions FOR EACH ROW EXECUTE FUNCTION register_revision('annual_plans','plan_id');
CREATE TRIGGER plan_revision_immutable BEFORE UPDATE OR DELETE ON plan_revisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE plan_objectives(id text PRIMARY KEY,plan_revision_id text NOT NULL REFERENCES plan_revisions(id),title text NOT NULL,responsible_id text REFERENCES principals(id),responsible_label text,due_on date,target numeric CHECK(target>=0),measure text NOT NULL CHECK(measure IN('completed','validated')),resources text,dependencies text);
CREATE TRIGGER objective_immutable BEFORE UPDATE OR DELETE ON plan_objectives FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE objective_cases(objective_id text NOT NULL REFERENCES plan_objectives(id),case_id text NOT NULL REFERENCES cases(id),PRIMARY KEY(objective_id,case_id));
CREATE TRIGGER objective_cases_immutable BEFORE UPDATE OR DELETE ON objective_cases FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE triage_assessments(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),pertinence text NOT NULL CHECK(pertinence IN('pending','low','medium','high')),urgency text NOT NULL CHECK(urgency IN('pending','low','medium','high')),proposed_priority text CHECK(proposed_priority IN('low','medium','high')),resolved_priority text CHECK(resolved_priority IN('low','medium','high')),recommendation text,reason text NOT NULL CHECK(length(trim(reason))>0),actor_id text NOT NULL REFERENCES principals(id),version int NOT NULL CHECK(version>0),at timestamptz NOT NULL DEFAULT now(),UNIQUE(case_id,version));
CREATE TABLE projects(id text PRIMARY KEY,name text NOT NULL,kind text NOT NULL DEFAULT 'initiative' CHECK(kind IN('initiative','event')),execution_state text NOT NULL DEFAULT 'draft' CHECK(execution_state IN('draft','planned','in_progress','completed','cancelled')),starts_on date,ends_on date,timezone text NOT NULL DEFAULT 'America/Santiago',location text,responsible_id text REFERENCES principals(id),protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz,CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on));
CREATE TRIGGER project_protect BEFORE INSERT ON projects FOR EACH ROW EXECUTE FUNCTION protect_object('project');
CREATE TABLE project_cases(project_id text NOT NULL REFERENCES projects(id),case_id text NOT NULL REFERENCES cases(id),PRIMARY KEY(project_id,case_id));
CREATE TABLE work_plan_revisions(id text PRIMARY KEY REFERENCES object_revisions(id),project_id text NOT NULL REFERENCES projects(id),version int NOT NULL CHECK(version>0),objective text NOT NULL,results_planned text NOT NULL,scope_included text NOT NULL,scope_excluded text NOT NULL,closing_criteria text NOT NULL,expected_evidence text NOT NULL,risks text NOT NULL,actor_id text NOT NULL REFERENCES principals(id),UNIQUE(project_id,version));
CREATE TRIGGER work_plan_register BEFORE INSERT ON work_plan_revisions FOR EACH ROW EXECUTE FUNCTION register_revision('projects','project_id');
CREATE TRIGGER work_plan_immutable BEFORE UPDATE OR DELETE ON work_plan_revisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE tasks(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),title text NOT NULL,kind text NOT NULL DEFAULT 'task' CHECK(kind IN('task','milestone')),description text,status text NOT NULL DEFAULT 'todo' CHECK(status IN('todo','in_progress','review','done','cancelled')),priority text NOT NULL DEFAULT 'medium' CHECK(priority IN('low','medium','high')),phase text CHECK(phase IN('pre','during','post')),due_on date,blocked boolean NOT NULL DEFAULT false,assignee_label text,version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE task_dependencies(project_id text NOT NULL,task_id text NOT NULL,depends_on_id text NOT NULL,PRIMARY KEY(task_id,depends_on_id),CHECK(task_id<>depends_on_id),FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id),FOREIGN KEY(project_id,depends_on_id) REFERENCES tasks(project_id,id));
CREATE TABLE task_assignees(task_id text NOT NULL REFERENCES tasks(id),contact_id text NOT NULL REFERENCES contacts(id),PRIMARY KEY(task_id,contact_id));
CREATE TABLE project_resources(project_id text NOT NULL REFERENCES projects(id),resource_id text NOT NULL REFERENCES resources(id),phase text NOT NULL CHECK(phase IN('planned','actual')),quantity numeric CHECK(quantity>=0),PRIMARY KEY(project_id,resource_id,phase));
CREATE TABLE risks(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),title text NOT NULL,impact text,likelihood text,owner_id text REFERENCES principals(id),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','mitigating','resolved')),resolution text,version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE issues(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),title text NOT NULL,reason text,owner_id text REFERENCES principals(id),due_on date,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','blocked','resolved')),resolution text,version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE follow_ups(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),issue_id text REFERENCES issues(id),owner_id text REFERENCES principals(id),due_on date,description text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','completed','cancelled')),resolution text,version int NOT NULL DEFAULT 1 CHECK(version>0));
